        /// The phase that failed.
        phase: &'static str,
        /// A joined summary of the reject findings.
        summary: String,
    },
    /// A filesystem operation failed.
    #[error("io error at {path}: {source}")]
    Io {
        /// The path involved.
        path: PathBuf,
        /// The underlying error.
        source: std::io::Error,
